-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     im.ITEM                                         AS \"Item ID\",     im.ITEM_DESC                                    AS \"Item Description\",     im.DEPT                                         AS \"Dept No\",     d.DEPT_NAME                                     AS \"Dept Name\",     im.CLASS                                        AS \"Class No\",     im.SUBCLASS                                     AS \"Subclass No\",     ril.LOCATION                                    AS \"Location ID\",     il.LOC_TYPE                                     AS \"LOC Type\",     CASE WHEN il.LOC_TYPE = 'S' THEN st.STORE_NAME             WHEN il.LOC_TYPE = 'W'                 THEN wh.WH_NAME             ELSE TO_CHAR(ril.LOCATION)     END                                                 AS location_name,      il.STATUS                                       AS \"Item LOC Status\",     CASE il.STATUS             WHEN 'A'                 THEN 'Active'             WHEN 'C'                 THEN 'Discontinued'             WHEN 'I'                 THEN 'Inactive'             WHEN 'D'                 THEN 'Delete'     END                                                 AS \"Item LOC Status DESC\",      ril.REPL_METHOD                                 AS \"Repl Method\",     CASE ril.REPL_METHOD             WHEN 'C'                 THEN 'Constant'             WHEN 'D'                 THEN 'Dynamic'             WHEN 'DI'                 THEN 'Dynamic Issues'             WHEN 'S'                 THEN 'Dynamic Seasonal'             WHEN 'F'                 THEN 'Floating Point'             WHEN 'M'                 THEN 'Min Max'             WHEN 'SO'                 THEN 'Store Orders'             WHEN 'T'                 THEN 'Time Supply'             WHEN 'TI'                 THEN 'Time Supply Issues'             WHEN 'E'                 THEN 'Time Supply Seasonal'             ELSE ril.REPL_METHOD     END                                                 AS \"Repl Method DESC\",      ril.STOCK_CAT                                   AS \"Stock Category\",     CASE ril.STOCK_CAT             WHEN 'C'                 THEN 'Cross-Docked'             WHEN 'D'                 THEN 'Direct to Store'             WHEN 'L'                 THEN 'WH Cross Link'             WHEN 'W'                 THEN 'Warehouse Stocked'             WHEN 'X'                 THEN 'PO Cross-link'             ELSE ril.STOCK_CAT     END                                                 AS \"Stock Category DESC\",      ril.REPL_ORDER_CTRL                             AS \"Order Control\",     CASE ril.REPL_ORDER_CTRL             WHEN 'A'                 THEN 'Automatic'             WHEN 'B'                 THEN 'Buyer Worksheet'             WHEN 'M'                 THEN 'Manual'             WHEN 'S'                 THEN 'Semi-Automatic'             ELSE ril.REPL_ORDER_CTRL     END                                                 AS \"Order Control DESC\",      ril.PRIMARY_REPL_SUPPLIER                       AS \"Supplier ID\",     ril.SOURCE_WH                                   AS \"Source Warehouse\",     ril.MIN_STOCK                                   AS \"Min Stock\",     ril.MAX_STOCK                                   AS \"Max Stock\",     mra.PRES_STOCK                                  AS \"Presentation Stock\",     ril.REVIEW_CYCLE                                AS \"Review Cycle\",     ril.WH_LEAD_TIME                                AS \"WH Lead Time\",     ril.PRIMARY_PACK_NO                             AS \"Primary Repl Pack\",     ril.NON_SCALING_IND                             AS \"Scaling Exempt IND\",     NVL(ril.MAX_STOCK, 0) - NVL(ril.MIN_STOCK, 0)   AS \"Repl Band\",     ils.STOCK_ON_HAND                               AS \"Current Soh\",     ils.AV_COST                                     AS \"Weighted Avg Cost\",     ROUND(NVL(ils.STOCK_ON_HAND, 0) * NVL(ils.AV_COST, 0), 2)AS \"Soh Cost Value\",     CASE WHEN NVL(ils.STOCK_ON_HAND, 0) = 0 THEN 'OUT OF STOCK'             WHEN NVL(ils.STOCK_ON_HAND, 0) &lt; NVL(ril.MIN_STOCK, 0)                 THEN 'BELOW MIN'             WHEN NVL(ils.STOCK_ON_HAND, 0) &gt; NVL(ril.MAX_STOCK, 0)                 THEN 'ABOVE MAX'             ELSE 'WITHIN RANGE'     END                                                 AS \"Stock Position\",      GREATEST(NVL(ril.MAX_STOCK, 0) - NVL(ils.STOCK_ON_HAND, 0), 0)AS \"Implied Roq\",     ril.LAST_UPDATE_DATETIME                        AS \"Last Updated\"  FROM     (

