SELECT ITEM, ITEM_DESC, DEPT, CLASS, SUBCLASS,                STATUS, PACK_IND, STANDARD_UOM         FROM   MFCS_RDS.RDS_WV_ITEM_MASTER         WHERE  TRAN_LEVEL = ITEM_LEVEL     )                                              im      JOIN  MFCS_RDS.RDS_WV_REPL_ITEM_LOC           ril  ON  im.ITEM       = ril.ITEM                                                        AND  ril.REPL_METHOD IS NOT NULL     JOIN  MFCS_RDS.RDS_WV_ITEM_LOC                 il   ON  ril.ITEM      = il.ITEM                                                        AND  ril.LOCATION  = il.LOC                                                        AND  ril.LOC_TYPE  = il.LOC_TYPE     JOIN  MFCS_RDS.RDS_WV_DEPS                     d    ON  im.DEPT       = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS                    c    ON  im.DEPT       = c.DEPT                                                        AND  im.CLASS      = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS                 sc   ON  im.DEPT       = sc.DEPT                                                        AND  im.CLASS      = sc.CLASS                                                        AND  im.SUBCLASS   = sc.SUBCLASS      LEFT JOIN MFCS_RDS.RDS_WV_STORE                st   ON  ril.LOCATION  = st.STORE     LEFT JOIN MFCS_RDS.RDS_WV_WH                   wh   ON  ril.LOCATION  = wh.WH     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH         ils  ON  ril.ITEM      = ils.ITEM                                                        AND  ril.LOCATION  = ils.LOC                                                        AND  ril.LOC_TYPE  = ils.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_MASTER_REPL_ATTR     mra  ON  ril.ITEM      = mra.ITEM                                                        AND  ril.LOCATION  = mra.LOCATION  WHERE     il.STATUS IN ('A', 'C')  </ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Item ID</ds:name><ds:datatype>varchar(25)</ds:datatype><ds:nullable>false</ds:nul