\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"3\"},{\"id\":\"5\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Supplier ID\"],\"expressionSourceColumns\":[\"Supplier ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Supplier ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Supplier ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"4\"},{\"id\":\"6\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Source Warehouse\"],\"expressionSourceColumns\":[\"Source Warehouse\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Source Warehouse\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Source Warehouse\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"5\"}],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 3 ────────────────────────────────────────────────────────────
SELECT ITEM, ITEM_DESC, DEPT, CLASS, SUBCLASS,\\n               STATUS, PACK_IND, STANDARD_UOM\\n        FROM   MFCS_RDS.RDS_WV_ITEM_MASTER\\n        WHERE  TRAN_LEVEL = ITEM_LEVEL\\n    )                                              im\\n\\n    JOIN  MFCS_RDS.RDS_WV_REPL_ITEM_LOC           ril  ON  im.ITEM       = ril.ITEM\\n                                                       AND  ril.REPL_METHOD IS NOT NULL\\n    JOIN  MFCS_RDS.RDS_WV_ITEM_LOC                 il   ON  ril.ITEM      = il.ITEM\\n                                                       AND  ril.LOCATION  = il.LOC\\n                                                       AND  ril.LOC_TYPE  = il.LOC_TYPE\\n    JOIN  MFCS_RDS.RDS_WV_DEPS                     d    ON  im.DEPT       = d.DEPT\\n    JOIN  MFCS_RDS.RDS_WV_CLASS                    c    ON  im.DEPT       = c.DEPT\\n                                                       AND  im.CLASS      = c.CLASS\\n    JOIN  MFCS_RDS.RDS_WV_SUBCLASS                 sc   ON  im.DEPT       = sc.DEPT\\n                                                       AND  im.CLASS      = sc.CLASS\\n                                                       AND  im.SUBCLASS   = sc.SUBCLASS\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_STORE                st   ON  ril.LOCATION  = st.STORE\\n    LEFT JOIN MFCS_RDS.RDS_WV_WH                   wh   ON  ril.LOCATION  = wh.WH\\n    LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH         ils  ON  ril.ITEM      = ils.ITEM\\n                                                       AND  ril.LOCATION  = ils.LOC\\n                                                       AND  ril.LOC_TYPE  = ils.LOC_TYPE\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_MASTER_REPL_ATTR     mra  ON  ril.ITEM      = mra.ITEM\\n                                                       AND  ril.LOCATION  = mra.LOCATION\\n\\nWHERE\\n    il.STATUS IN ('A', 'C')\\n\\n\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-07-29T16:30:19.803+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_526_Replenishment_Parameters'","parent-namespace":"ReCommon","parent-name":"RPT_526_Replenishment_Parameters","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_526_Replenishment_Parameters'"}
